        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "Bolivia, celle a pagamento",
        "testo_it": "Nel carcere di San Pedro a La Paz, Bolivia, i detenuti gestiscono autonomamente le celle a pagamento.",
        "priorita": "Bassa",
